<?php
namespace App\Http\Controllers;
use App\Models\{TeacherAssignment,StudentEnrollment,TeacherAssessment,TeacherAssessmentMark,TeacherTermRemark};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class TeacherExaminationExtensionController extends Controller {
 private function school(Request $r): int {abort_unless($r->user()?->school_id,403);return (int)$r->user()->school_id;}
 private function assignments(Request $r){$q=TeacherAssignment::with(['schoolClass','section','subject','academicYear'])->where('school_id',$this->school($r))->where('status',1);if(!$r->user()->hasAnyRole(['Super Admin','Admin']))$q->where('teacher_user_id',$r->user()->id);return $q->get();}
 private function assignment(Request $r,int $id): TeacherAssignment {$a=$this->assignments($r)->firstWhere('id',$id);abort_unless($a,403,'Not assigned to this section.');return $a;}
 private function students(TeacherAssignment $a){return StudentEnrollment::with('student')->where('school_id',$a->school_id)->where('academic_year_id',$a->academic_year_id)->where('school_class_id',$a->school_class_id)->where('section_id',$a->section_id)->where('is_current',1)->orderBy('roll_no')->get();}
 private function enrollment(TeacherAssignment $a,int $id): StudentEnrollment {return $this->students($a)->firstWhere('id',$id) ?? abort(403,'Student is not in the assigned section.');}
 public function health(Request $r){$assignments=$this->assignments($r);$assignment=null;$students=collect();$records=collect();$day=$r->query('date',date('Y-m-d'));if($r->filled('assignment_id')){$assignment=$this->assignment($r,(int)$r->query('assignment_id'));$students=$this->students($assignment);$records=DB::table('teacher_student_health_records')->where('school_id',$this->school($r))->whereIn('student_enrollment_id',$students->pluck('id'))->where('recorded_on',$day)->get()->keyBy('student_enrollment_id');}return view('teacher.examination.health',compact('assignments','assignment','students','records','day'));}
 public function saveHealth(Request $r){$d=$r->validate(['assignment_id'=>'required|integer','recorded_on'=>'required|date','records'=>'required|array','records.*.height_cm'=>'nullable|numeric|between:0,300','records.*.weight_kg'=>'nullable|numeric|between:0,500','records.*.blood_group'=>'nullable|string|max:8','records.*.notes'=>'nullable|string|max:3000']);$a=$this->assignment($r,(int)$d['assignment_id']);$allowed=$this->students($a)->pluck('id')->map(fn($id)=>(string)$id)->all();DB::transaction(function()use($r,$d,$a,$allowed){foreach($d['records'] as $id=>$row){if(!in_array((string)$id,$allowed,true))throw ValidationException::withMessages(['records'=>'Invalid student.']);$values=['height_cm'=>$row['height_cm']??null,'weight_kg'=>$row['weight_kg']??null,'blood_group'=>$row['blood_group']??null,'notes'=>$row['notes']??null];if(count(array_filter($values,fn($v)=>$v!==null&&$v!==''))===0)continue;DB::table('teacher_student_health_records')->updateOrInsert(['school_id'=>$a->school_id,'student_enrollment_id'=>$id,'recorded_on'=>$d['recorded_on']],$values+['teacher_user_id'=>$r->user()->id,'updated_at'=>now(),'created_at'=>now()]);}});return redirect()->route('teacher.examination.health',['assignment_id'=>$a->id,'date'=>$d['recorded_on']])->with('success','Health records saved.');}
 public function skills(Request $r){$assignments=$this->assignments($r);$assignment=null;$students=collect();$descriptors=collect();$ratings=collect();$term=$r->query('term','Term 1');if($r->filled('assignment_id')){$assignment=$this->assignment($r,(int)$r->query('assignment_id'));$students=$this->students($assignment);$descriptors=DB::table('teacher_skill_descriptors')->where('teacher_assignment_id',$assignment->id)->where('school_id',$this->school($r))->where('term',$term)->orderBy('skill')->get();$ratings=DB::table('teacher_student_skill_ratings')->whereIn('teacher_skill_descriptor_id',$descriptors->pluck('id'))->whereIn('student_enrollment_id',$students->pluck('id'))->get()->keyBy(fn($v)=>$v->teacher_skill_descriptor_id.':'.$v->student_enrollment_id);}return view('teacher.examination.skills',compact('assignments','assignment','students','descriptors','ratings','term'));}
 public function addSkill(Request $r){$d=$r->validate(['assignment_id'=>'required|integer','term'=>'required|string|max:80','skill'=>'required|string|max:160']);$a=$this->assignment($r,(int)$d['assignment_id']);DB::table('teacher_skill_descriptors')->updateOrInsert(['school_id'=>$a->school_id,'teacher_assignment_id'=>$a->id,'term'=>$d['term'],'skill'=>trim($d['skill'])],['updated_at'=>now(),'created_at'=>now()]);return redirect()->route('teacher.examination.skills',['assignment_id'=>$a->id,'term'=>$d['term']])->with('success','Skill descriptor added.');}
 public function saveSkills(Request $r){$d=$r->validate(['assignment_id'=>'required|integer','term'=>'required|string|max:80','ratings'=>'required|array','ratings.*'=>'array','ratings.*.*'=>'nullable|in:Excellent,Good,Satisfactory,Needs Improvement']);$a=$this->assignment($r,(int)$d['assignment_id']);$allowed=$this->students($a)->pluck('id')->map(fn($id)=>(string)$id)->all();$skills=DB::table('teacher_skill_descriptors')->where('school_id',$a->school_id)->where('teacher_assignment_id',$a->id)->where('term',$d['term'])->pluck('id')->map(fn($id)=>(string)$id)->all();DB::transaction(function()use($r,$d,$allowed,$skills){foreach($d['ratings'] as $skillId=>$rows){if(!in_array((string)$skillId,$skills,true))throw ValidationException::withMessages(['ratings'=>'Invalid descriptor.']);foreach($rows as $studentId=>$rating){if(!in_array((string)$studentId,$allowed,true))throw ValidationException::withMessages(['ratings'=>'Invalid student.']);if($rating===null||$rating===''){DB::table('teacher_student_skill_ratings')->where('teacher_skill_descriptor_id',$skillId)->where('student_enrollment_id',$studentId)->delete();continue;}DB::table('teacher_student_skill_ratings')->updateOrInsert(['teacher_skill_descriptor_id'=>$skillId,'student_enrollment_id'=>$studentId],['teacher_user_id'=>$r->user()->id,'rating'=>$rating,'updated_at'=>now(),'created_at'=>now()]);}}});return redirect()->route('teacher.examination.skills',['assignment_id'=>$a->id,'term'=>$d['term']])->with('success','Skill ratings saved.');}
 public function reports(Request $r){$assignments=$this->assignments($r);$assignment=null;$students=collect();$assessments=collect();$marks=collect();$remarks=collect();$term=$r->query('term','Term 1');if($r->filled('assignment_id')){$assignment=$this->assignment($r,(int)$r->query('assignment_id'));$students=$this->students($assignment);$assessments=TeacherAssessment::where('school_id',$this->school($r))->where('teacher_assignment_id',$assignment->id)->where('term',$term)->orderBy('assessment_date')->get();$marks=TeacherAssessmentMark::whereIn('assessment_id',$assessments->pluck('id'))->whereIn('student_enrollment_id',$students->pluck('id'))->get()->keyBy(fn($m)=>$m->assessment_id.':'.$m->student_enrollment_id);$remarks=TeacherTermRemark::where('school_id',$this->school($r))->where('teacher_assignment_id',$assignment->id)->where('term',$term)->whereIn('student_enrollment_id',$students->pluck('id'))->get()->keyBy('student_enrollment_id');}return view('teacher.examination.reports',compact('assignments','assignment','students','assessments','marks','remarks','term'));}
}
